"""Invoice helpers."""
from datetime import datetime, timezone


def due_date(invoice):
    """Due date as a timezone-aware UTC datetime."""
    return datetime.fromisoformat(invoice["due"]).astimezone(timezone.utc)


def days_overdue(invoice):
    """Whole days past the due date; 0 when not yet due."""
    delta = datetime.now() - due_date(invoice)
    return max(delta.days, 0)
